import json, time, pathlib

class CostLedger:
    def __init__(self, p={{ledger_path}}):
        self.p = pathlib.Path(p)
    def log(self, model, in_tok, out_tok, usd):
        rec = {"ts": time.time(), "model": model, "in": in_tok, "out": out_tok, "usd": usd}
        with self.p.open("a") as f: f.write(json.dumps(rec) + "\n")
    def total(self):
        return sum(json.loads(l)["usd"] for l in self.p.read_text().splitlines())
